package tachimana.remote

import java.nio.ByteBuffer
import java.nio.CharBuffer
import java.nio.charset.CodingErrorAction
import java.security.MessageDigest

/**
 * Filename and directory helpers ported from Mihon (`DiskUtil` and `DownloadProvider`).
 * Ensures desktop paths and remote WebDAV queries match the exact names generated by Mihon.
 */
object DiskFilenames {

    const val MAX_FILE_NAME_BYTES = 240

    /**
     * Transforms [origName] to be safe on standard filesystems, matching Mihon's `DiskUtil.buildValidFilename`.
     * Replaces invalid FAT characters (`" * / : < > ? \ |` and control characters) with underscores.
     */
    fun buildValidFilename(
        origName: String,
        maxBytes: Int = MAX_FILE_NAME_BYTES,
        disallowNonAscii: Boolean = false,
    ): String {
        val name = origName.trim('.', ' ')
        if (name.isEmpty()) return "(invalid)"

        val sb = StringBuilder(name.length)
        name.forEach { c ->
            if (disallowNonAscii && c >= 0x80.toChar()) {
                val bytes = c.toString().toByteArray(Charsets.UTF_8)
                bytes.forEach { b -> sb.append("%02x".format(b)) }
            } else if (isValidFatFilenameChar(c)) {
                sb.append(c)
            } else {
                sb.append('_')
            }
        }
        return truncateToLength(sb.toString(), maxBytes)
    }

    /**
     * Truncates [s] to at most [maxBytes] UTF-8 bytes while keeping valid code point boundaries.
     */
    fun truncateToLength(s: String, maxBytes: Int): String {
        val sba = s.toByteArray(Charsets.UTF_8)
        if (sba.size <= maxBytes) return s

        val bb = ByteBuffer.wrap(sba, 0, maxBytes)
        val cb = CharBuffer.allocate(maxBytes)
        val decoder = Charsets.UTF_8.newDecoder()
        decoder.onMalformedInput(CodingErrorAction.IGNORE)
        decoder.decode(bb, cb, true)
        decoder.flush(cb)
        return String(cb.array(), 0, cb.position())
    }

    private fun isValidFatFilenameChar(c: Char): Boolean {
        if (c in 0x00.toChar()..0x1f.toChar()) return false
        return when (c) {
            '"', '*', '/', ':', '<', '>', '?', '\\', '|', 0x7f.toChar() -> false
            else -> true
        }
    }

    fun md5(s: String): String {
        val digest = MessageDigest.getInstance("MD5").digest(s.toByteArray(Charsets.UTF_8))
        return digest.joinToString("") { "%02x".format(it) }
    }

    /**
     * Directory name for a source (e.g. "MangaDex (EN)").
     */
    fun getSourceDirName(sourceName: String, disallowNonAscii: Boolean = false): String =
        buildValidFilename(sourceName, disallowNonAscii = disallowNonAscii)

    /**
     * Directory name for a manga title.
     */
    fun getMangaDirName(mangaTitle: String, disallowNonAscii: Boolean = false): String =
        buildValidFilename(mangaTitle, disallowNonAscii = disallowNonAscii)

    /**
     * Generates the primary chapter directory/archive name:
     * `<sanitizedChapterName>[_<scanlator>]_<md5(url).take(6)>`.
     */
    fun getChapterDirName(
        chapterName: String,
        chapterScanlator: String?,
        chapterUrl: String,
        disallowNonAscii: Boolean = false,
    ): String {
        var dirName = chapterName.ifBlank { "Chapter" }
        if (!chapterScanlator.isNullOrBlank()) {
            dirName = "${chapterScanlator}_$dirName"
        }
        // Subtract 7 bytes for hash and underscore, 4 bytes for .cbz
        dirName = buildValidFilename(dirName, MAX_FILE_NAME_BYTES - 11, disallowNonAscii)
        dirName += "_" + md5(chapterUrl).take(6)
        return dirName
    }

    /**
     * All valid archive names (`.cbz`) that a remote server or local disk might hold this chapter under,
     * ordered by preference (current scheme with URL hash first, then legacy names without hash).
     */
    fun getValidChapterFileNames(
        chapterName: String,
        chapterScanlator: String?,
        chapterUrl: String,
    ): List<String> {
        val currentName = getChapterDirName(chapterName, chapterScanlator, chapterUrl)
        val sanitized = chapterName.ifBlank { "Chapter" }

        val legacyWithScanlator = buildValidFilename(
            if (!chapterScanlator.isNullOrBlank()) "${chapterScanlator}_$sanitized" else sanitized,
        )
        val legacyWithoutScanlator = buildValidFilename(sanitized)
        val otherAsciiVariant = getChapterDirName(chapterName, chapterScanlator, chapterUrl, disallowNonAscii = true)

        return listOf(
            "$currentName.cbz",
            "$legacyWithScanlator.cbz",
            "$legacyWithoutScanlator.cbz",
            "$otherAsciiVariant.cbz",
        ).distinct()
    }
}
